import AppKit
import TabsPluginSDK

/// The main window: one workspace, its tabs and panes, and the header
/// strip over each pane. Built on first show; its frame is saved on close.
@MainActor
final class WindowController: NSWindowController, NSWindowDelegate {
    let workspace: Workspace
    private var frameObserver: NSObjectProtocol?

    init(workspace: Workspace) {
        self.workspace = workspace
        let window = NSWindow(contentRect: .zero, styleMask: [.titled, .closable, .resizable], backing: .buffered, defer: true)
        window.title = workspace.name
        super.init(window: window)
        window.delegate = self
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) { fatalError("init(coder:) is not supported") }

    func showWorkspace() {
        guard let window else { return }
        window.contentView = WorkspaceView(workspace: workspace)
        window.setFrameAutosaveName("workspace")
        window.makeKeyAndOrderFront(nil)
    }

    func windowWillClose(_ notification: Notification) {
        workspace.saveLayout()
        if let frameObserver { NotificationCenter.default.removeObserver(frameObserver) }
    }

    func windowDidBecomeKey(_ notification: Notification) {
        workspace.activePane?.focus()
    }

    func windowDidResize(_ notification: Notification) {
        workspace.layoutDidChange()
    }

    func windowDidChangeScreen(_ notification: Notification) {
        workspace.layoutDidChange()
    }
}
